package license

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
)

// Master Developer Ed25519 Public Key (32 bytes hex)
// Generated by Gonzhilaz Dev for 13C Payment Gateway License Enforcement
const MasterDeveloperPublicKeyHex = "0c3b91b33c1596b8af5110b0c72074960cc25e92e0137628661d13a2ee6e8770"

type LicenseStatus string

const (
	StatusActive     LicenseStatus = "ACTIVE"
	StatusExpired    LicenseStatus = "EXPIRED"
	StatusRevoked    LicenseStatus = "REVOKED"
	StatusUnlicensed LicenseStatus = "UNLICENSED"
)

// LicensePayload contains digitally signed metadata
type LicensePayload struct {
	LicenseID    string    `json:"license_id"`
	Licensee     string    `json:"licensee"`
	Domain       string    `json:"domain"`
	Tier         string    `json:"tier"`
	IssuedAt     time.Time `json:"issued_at"`
	ExpiresAt    time.Time `json:"expires_at"`
	HeartbeatURL string    `json:"heartbeat_url"`
}

// Manager controls active license validation and remote kill-switch heartbeat
type Manager struct {
	mu           sync.RWMutex
	status       LicenseStatus
	payload      *LicensePayload
	lastVerified time.Time
	stopChan     chan struct{}
	httpClient   *http.Client
}

var (
	globalManager *Manager
	once          sync.Once
)

// GetManager returns the singleton license manager instance
func GetManager() *Manager {
	once.Do(func() {
		globalManager = &Manager{
			status:     StatusUnlicensed,
			stopChan:   make(chan struct{}),
			httpClient: &http.Client{Timeout: 8 * time.Second},
		}
	})
	return globalManager
}

// VerifyAndActivate validates offline Ed25519 signature and starts background heartbeat
func (m *Manager) VerifyAndActivate(token string, defaultHeartbeatURL string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	token = strings.TrimSpace(token)
	if token == "" {
		m.status = StatusUnlicensed
		return errors.New("empty license token")
	}

	payload, err := VerifyToken(token)
	if err != nil {
		m.status = StatusUnlicensed
		return fmt.Errorf("cryptographic license verification failed: %w", err)
	}

	// Check Expiry Date
	if time.Now().After(payload.ExpiresAt) {
		m.status = StatusExpired
		return fmt.Errorf("license expired on %s", payload.ExpiresAt.Format("2006-01-02"))
	}

	if payload.HeartbeatURL == "" && defaultHeartbeatURL != "" {
		payload.HeartbeatURL = defaultHeartbeatURL
	}

	m.payload = payload
	m.status = StatusActive
	m.lastVerified = time.Now()

	log.Printf("[LICENSE ACTIVE] Validated for '%s' (Tier: %s, Expires: %s)",
		payload.Licensee, payload.Tier, payload.ExpiresAt.Format("2006-01-02"))

	return nil
}

// StartHeartbeatDaemon begins periodic ping to developer's remote license server
func (m *Manager) StartHeartbeatDaemon(ctx context.Context) {
	go func() {
		ticker := time.NewTicker(6 * time.Hour)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-m.stopChan:
				return
			case <-ticker.C:
				m.checkRemoteHeartbeat()
			}
		}
	}()
}

func (m *Manager) checkRemoteHeartbeat() {
	m.mu.RLock()
	payload := m.payload
	heartbeatURL := ""
	if payload != nil {
		heartbeatURL = payload.HeartbeatURL
	}
	m.mu.RUnlock()

	if heartbeatURL == "" {
		return
	}

	reqBody, _ := json.Marshal(map[string]interface{}{
		"license_id": payload.LicenseID,
		"licensee":   payload.Licensee,
		"timestamp":  time.Now().UTC().Unix(),
	})

	resp, err := m.httpClient.Post(heartbeatURL, "application/json", bytes.NewReader(reqBody))
	if err != nil {
		log.Printf("[LICENSE HEARTBEAT WARN] Remote license server check failed (grace period active): %v", err)
		return
	}
	defer resp.Body.Close()

	var res struct {
		Status string `json:"status"` // "ACTIVE", "REVOKED", "SUSPENDED"
		Reason string `json:"reason"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&res); err != nil {
		return
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	if res.Status == "REVOKED" || res.Status == "SUSPENDED" {
		m.status = StatusRevoked
		log.Printf("[LICENSE KILL-SWITCH TRIGGERED] System revoked by developer! Reason: %s", res.Reason)
	} else if res.Status == "ACTIVE" {
		m.status = StatusActive
		m.lastVerified = time.Now()
	}
}

// IsOperational returns true if the system is legally licensed and not revoked
func (m *Manager) IsOperational() (bool, string) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	if m.status == StatusActive {
		return true, "System operational"
	}

	switch m.status {
	case StatusRevoked:
		return false, "SYSTEM ACCESS REVOKED BY DEVELOPER. Contact licensing administrator."
	case StatusExpired:
		return false, "LICENSE EXPIRED. Please renew license key."
	default:
		return false, "SYSTEM UNLICENSED. Valid 13C Gateway license key is required to operate."
	}
}

// GetStatus returns current license status and metadata
func (m *Manager) GetStatus() map[string]interface{} {
	m.mu.RLock()
	defer m.mu.RUnlock()

	res := map[string]interface{}{
		"status":        m.status,
		"last_verified": m.lastVerified,
	}
	if m.payload != nil {
		res["licensee"] = m.payload.Licensee
		res["expires_at"] = m.payload.ExpiresAt
		res["tier"] = m.payload.Tier
	}
	return res
}

// VerifyToken decodes and checks the Ed25519 signature of a license token
func VerifyToken(token string) (*LicensePayload, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 2 {
		return nil, errors.New("invalid license token format, expected payload.signature")
	}

	payloadBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, fmt.Errorf("failed to decode payload: %w", err)
	}

	sigBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("failed to decode signature: %w", err)
	}

	pubKeyBytes, err := hex.DecodeString(MasterDeveloperPublicKeyHex)
	if err != nil || len(pubKeyBytes) != ed25519.PublicKeySize {
		return nil, errors.New("invalid master public key configuration")
	}

	// Cryptographic Ed25519 Verification
	if !ed25519.Verify(pubKeyBytes, payloadBytes, sigBytes) {
		return nil, errors.New("tampered or invalid digital signature")
	}

	var payload LicensePayload
	if err := json.Unmarshal(payloadBytes, &payload); err != nil {
		return nil, fmt.Errorf("invalid license JSON structure: %w", err)
	}

	return &payload, nil
}
